// Yolculuk akışının saf mantığı: aşama toplamları, seçili adımın girenleri ve çıkanları, düşüşler ve yazımlar.
// Yerleşimi `sankey-flow` hesaplar; sayılar ABACUS'tandır (sankey-flow-format üzerinden).
import { flowShareText, flowValueText, layoutSankey, validLinks, type SankeyLinkInput, type SankeyNodeInput } from "../sankey-flow/sankey-flow-format";

export interface JourneyData {
  nodes: SankeyNodeInput[];
  links: SankeyLinkInput[];
  /** Aşama adları, soldan sağa ("Ziyaret", "Hesap", "Kurulum", "İlk hafta", "Plan"). */
  stages: string[];
}

export interface JourneyFacts {
  /** İlk aşamadaki toplam (başlıktaki büyük sayı). */
  total: number;
  /** Son aşamadaki (ücretli plan gibi) toplam. */
  finalTotal: number;
  nodes: Map<string, { id: string; label: string; column: number; value: number; muted: boolean }>;
  columns: number;
}

export function journeyFacts(data: JourneyData): JourneyFacts {
  const layout = layoutSankey(data.nodes, data.links, 100);
  const nodes = new Map(layout.nodes.map(node => [node.id, { id: node.id, label: node.label, column: node.column, value: node.value, muted: node.muted }]));
  const final = layout.nodes.filter(node => node.column === layout.columns - 1 && !node.muted).reduce((sum, node) => sum + node.value, 0);
  return { total: layout.total, finalTotal: final, nodes, columns: layout.columns };
}

export interface FlowRow { id: string; label: string; value: number; /** Düğümün toplamına göre pay metni. */ share: string; drop: boolean }
export interface NodeSummary { label: string; value: number; /** İlk aşamaya göre pay metni. */ shareOfTotal: string; incoming: FlowRow[]; outgoing: FlowRow[] }

/** Seçili adımın girenleri ve çıkanları; paylar adımın kendi toplamına göredir. */
export function nodeSummary(data: JourneyData, facts: JourneyFacts, id: string): NodeSummary | null {
  const node = facts.nodes.get(id);
  if (!node) return null;
  const links = validLinks(data.nodes, data.links);
  const row = (link: SankeyLinkInput, other: string): FlowRow => { const target = facts.nodes.get(other); return { id: other, label: target?.label ?? other, value: link.value, share: flowShareText(link.value, node.value), drop: !!target?.muted }; };
  return {
    label: node.label,
    value: node.value,
    shareOfTotal: flowShareText(node.value, facts.total),
    incoming: links.filter(link => link.target === id).sort((a, b) => b.value - a.value).map(link => row(link, link.source)),
    outgoing: links.filter(link => link.source === id).sort((a, b) => b.value - a.value).map(link => row(link, link.target)),
  };
}

export interface DropRow { from: string; value: number; /** Düşen kolun, çıktığı adımın toplamına payı. */ share: string }
/** En büyük düşüşler: düşen (muted) düğümlere giden şeritler, büyükten küçüğe. */
export function topDrops(data: JourneyData, facts: JourneyFacts, count = 3): DropRow[] {
  return validLinks(data.nodes, data.links)
    .filter(link => facts.nodes.get(link.target)?.muted)
    .map(link => ({ from: facts.nodes.get(link.source)?.label ?? link.source, value: link.value, share: flowShareText(link.value, facts.nodes.get(link.source)?.value ?? 0) }))
    .sort((a, b) => b.value - a.value)
    .slice(0, count);
}

export const countText = (value: number) => flowValueText("count", value);
export const shareText = (value: number, base: number) => flowShareText(value, base);

/** Kanal değişince canlı bölge: "16.965 ziyaret, 1.018 ücretli plan". */
export const channelAnnouncement = (facts: JourneyFacts, firstLabel: string, finalLabel: string) => `${countText(facts.total)} ${firstLabel}, ${countText(facts.finalTotal)} ${finalLabel}`;

.root { container-type: inline-size; display: grid; min-width: 0; gap: var(--space-4); padding: var(--space-6); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); color: var(--foreground); }
.header { display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: space-between; gap: var(--space-3); }
.titles { min-width: 0; }
.title { margin: 0; color: var(--text-secondary); font-size: var(--text-sm); font-weight: 400; }
.total { margin: 2px 0 0; font-family: var(--font-display); font-size: var(--text-4xl); letter-spacing: var(--tracking-display); line-height: var(--leading-display); font-variant-numeric: tabular-nums; }
.subtitle { margin: 2px 0 0; color: var(--text-secondary); font-size: var(--text-sm); }
.body { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--space-4); }
.diagram { min-width: 0; }
.panel { min-width: 0; padding: var(--space-4); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-muted); font-size: var(--text-sm); }
.panelTitle { margin: 0; font-size: var(--text-sm); font-weight: 500; }
.panelValue { margin: 2px 0 0; font-family: var(--font-display); font-size: var(--text-2xl); letter-spacing: var(--tracking-display); font-variant-numeric: tabular-nums; }
.panelNote { margin: 0 0 var(--space-3); color: var(--text-secondary); font-size: var(--text-xs); }
.panel h5 { margin: var(--space-3) 0 var(--space-1); color: var(--text-secondary); font-size: var(--text-xs); font-weight: 400; }
.panel ul { display: grid; gap: 2px; margin: 0; padding: 0; list-style: none; }
.panel li { display: grid; grid-template-columns: minmax(0, 1fr) auto 3.5rem; gap: var(--space-2); align-items: baseline; font-variant-numeric: tabular-nums; }
.panel li small { color: var(--text-muted); text-align: right; }
.panel li[data-drop] span { color: var(--text-secondary); }
.hint { margin: 0 0 var(--space-3); color: var(--text-muted); }
.dropsTitle { margin-top: var(--space-4) !important; }
.tableToggle { display: flex; }
.table { width: 100%; border-collapse: collapse; font-size: var(--text-sm); font-variant-numeric: tabular-nums; }
.table th, .table td { padding: var(--space-2); border-bottom: 1px solid var(--border-subtle); text-align: right; }
.table th:first-child, .table td:first-child, .table td:nth-child(2) { text-align: left; }
.table thead th { color: var(--text-secondary); font-size: var(--text-xs); font-weight: 400; }
.table tbody th { font-weight: 400; text-align: left; }
.error { display: flex; align-items: center; justify-content: center; gap: var(--space-3); padding: var(--space-8) 0; color: var(--danger); }
.empty { margin: 0; padding: var(--space-8) 0; color: var(--text-muted); text-align: center; }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
@container (min-width: 860px) { .body { grid-template-columns: minmax(0, 1fr) 18rem; align-items: start; } }
@container (max-width: 560px) { .root { padding: var(--space-4); } .total { font-size: var(--text-3xl); } }

"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";
import { AnimatedCounter } from "../animated-counter/animated-counter";
import { Button } from "../button/button";
import { useReducedMotionSafe } from "../lib/viz-utils";
import { SankeyFlow } from "../sankey-flow/sankey-flow";
import SegmentedControl from "../segmented-control/segmented-control";
import { Skeleton } from "../skeleton/skeleton";
import { Switch } from "../switch/switch";
import { channelAnnouncement, countText, journeyFacts, nodeSummary, shareText, topDrops, type JourneyData } from "./journey-flow-format";
import styles from "./journey-flow.module.css";

export type { JourneyData };
export interface JourneyChannel { value: string; label: string }

/** Kullanıcıların bir sürecin aşamaları boyunca nereye gittiğini (devam edenler ve düşenler ayrı kollar), kanala göre ve hazır yan panelle görmek için kullanın; doğrusal ve dallanmayan süreç için huni grafiği, elde tutma için kohort tablosu daha doğrudur. */
export interface JourneyFlowProps {
  /** Seçili kanalın akışı. Düşen kolları `muted` düğümle verin; yoksa null (\"Bu kanal için veri yok\"). */
  data: JourneyData | null;
  channels: JourneyChannel[];
  channel: string;
  onChannelChange: (value: string) => void;
  title?: string | undefined;
  /** Alt cümle: örneğin "Ağustos ayında ziyaret, ilk oturumdan plana kadar izlendi" (ABACUS `date.monthName`). */
  subtitle?: string | undefined;
  /** Başlıktaki büyük toplamın, canlı bölgedeki ve sayfadaki adı: "ziyaret". */
  totalLabel?: string | undefined;
  /** Son aşamanın adı (canlı bölge için): "ücretli plan". */
  finalLabel?: string | undefined;
  status?: "ready" | "loading" | "error" | undefined;
  onRetry?: (() => void) | undefined;
}

export function JourneyFlow({ data, channels, channel, onChannelChange, title = "Kullanıcı yolculuğu", subtitle, totalLabel = "ziyaret", finalLabel = "ücretli plan", status = "ready", onRetry }: JourneyFlowProps) {
  const reduced = useReducedMotionSafe();
  const panelId = useId();
  const [selected, setSelected] = useState<string | null>(null);
  const [table, setTable] = useState(false);
  const [announce, setAnnounce] = useState("");
  const facts = useMemo(() => data ? journeyFacts(data) : null, [data]);
  const summary = data && facts && selected ? nodeSummary(data, facts, selected) : null;
  const drops = useMemo(() => data && facts ? topDrops(data, facts) : [], [data, facts]);

  // Kanal değişince "{n} ziyaret, {n} ücretli plan" duyurulur; seçili adım yeni kanalda yoksa kalkar.
  const first = useRef(true);
  useEffect(() => {
    if (first.current) { first.current = false; return; }
    if (facts) setAnnounce(channelAnnouncement(facts, totalLabel, finalLabel));
    setSelected(current => current && facts?.nodes.has(current) ? current : null);
  }, [channel]); // eslint-disable-line react-hooks/exhaustive-deps

  const labelOf = (id: string) => facts?.nodes.get(id)?.label ?? id;

  return <section className={styles.root} data-reduced={reduced || undefined} aria-label={title}>
    <header className={styles.header}>
      <div className={styles.titles}>
        <h3 className={styles.title}>{title}</h3>
        {facts && <p className={styles.total} aria-label={`${countText(facts.total)} ${totalLabel}`}><AnimatedCounter value={facts.total} /></p>}
        {subtitle && <p className={styles.subtitle}>{subtitle}</p>}
      </div>
      <SegmentedControl label="Kanal" value={channel} onValueChange={onChannelChange} options={channels} />
    </header>

    {status === "loading" && <Skeleton label="Yolculuk yükleniyor" lines={6} />}
    {status === "error" && <div className={styles.error} role="alert"><span>Yüklenemedi.</span>{onRetry && <Button size="sm" variant="secondary" onClick={onRetry}>Yeniden dene</Button>}</div>}
    {status === "ready" && !data && <p className={styles.empty}>Bu kanal için veri yok.</p>}

    {status === "ready" && data && facts && <>
      <div className={styles.body}>
        <div className={styles.diagram}>
          <SankeyFlow bare label={title} nodes={data.nodes} links={data.links} columnLabels={data.stages} selectedId={selected} onSelectedChange={setSelected} />
        </div>
        <aside className={styles.panel} id={panelId} aria-label="Seçili adım">
          {!summary ? <p className={styles.hint}>Nereden geldiğini ve nereye gittiğini görmek için bir adım seçin.</p> : <>
            <h4 className={styles.panelTitle}>{summary.label}</h4>
            <p className={styles.panelValue}><AnimatedCounter value={summary.value} /></p>
            <p className={styles.panelNote}>İlk aşamanın payı {summary.shareOfTotal}</p>
            {summary.incoming.length > 0 && <><h5>Nereden geldi</h5><ul>{summary.incoming.map(row => <li key={row.id}><span>{row.label}</span><b>{countText(row.value)}</b><small>{row.share}</small></li>)}</ul></>}
            {summary.outgoing.length > 0 && <><h5>Nereye gitti</h5><ul>{summary.outgoing.map(row => <li key={row.id} data-drop={row.drop || undefined}><span>{row.drop ? `↓ ${row.label}` : row.label}</span><b>{countText(row.value)}</b><small>{row.share}</small></li>)}</ul></>}
          </>}
          {drops.length > 0 && <><h5 className={styles.dropsTitle}>En büyük düşüşler</h5><ul className={styles.drops}>{drops.map((row, at) => <li key={at}><span>↓ {row.from}</span><b>{countText(row.value)}</b><small>{row.share}</small></li>)}</ul></>}
        </aside>
      </div>

      <div className={styles.tableToggle}>
        <Switch label="Akış tablosu" checked={table} onCheckedChange={setTable} aria-expanded={table} aria-controls={`${panelId}-table`} />
      </div>
      {table && <table id={`${panelId}-table`} className={styles.table}>
        <caption className={styles.srOnly}>{title}, akış tablosu</caption>
        <thead><tr><th scope="col">Kaynak</th><th scope="col">Hedef</th><th scope="col">Kullanıcı</th><th scope="col">Kaynağın payı</th></tr></thead>
        <tbody>{data.links.filter(link => link.value > 0).map(link => <tr key={`${link.source}>${link.target}`}><th scope="row">{labelOf(link.source)}</th><td>{labelOf(link.target)}</td><td>{countText(link.value)}</td><td>{shareText(link.value, facts.nodes.get(link.source)?.value ?? 0)}</td></tr>)}</tbody>
      </table>}
    </>}
    <p className={styles.srOnly} role="status" aria-live="polite" aria-atomic="true">{announce}</p>
  </section>;
}

export default JourneyFlow;
